/** An icon from a Material Symbols path on Google's 960-unit grid (y from -960 to 0, moved down into view). */
internal fun symbol(name: String, path: String, autoMirror: Boolean = false): ImageVector =
    ImageVector.Builder(
        name = "Symbols.$name",
        defaultWidth = 24.dp,
        defaultHeight = 24.dp,
        viewportWidth = 960f,
        viewportHeight = 960f,
        autoMirror = autoMirror
    )
        .addGroup(translationY = 960f)
        .addPath(pathData = addPathNodes(path), fill = SolidColor(Color.Black))
        .clearGroup()
        .build()
